(()=>{
 const q=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let data,chosen,loadedExample;
 const dialog=document.createElement('dialog');dialog.id='leanDialog';dialog.setAttribute('aria-labelledby','leanTitle');
 dialog.innerHTML=`<div class="lean-heading"><div><h2 id="leanTitle">Lean proof playground</h2><p>Small proofs connected to the graph</p></div><button id="leanClose">Close Lean</button></div><div class="lean-toolbar"><label for="leanExample">Example</label><select id="leanExample"></select><button id="leanLoad">Load example in editor</button><a id="leanExternal" target="_blank" rel="noopener">Open full editor ↗</a><a id="leanDownload" download>Download bundled .lean</a></div><p id="leanScope"></p><p class="extraction">The embedded editor sends code to live.lean-lang.org for checking. Read its goals, errors, and warnings there. Edits stay in that editor; switching examples resets them. Use the editor’s share/save controls to keep your work. MathUni does not mark a graph claim verified from this session.</p><details><summary>Bundled example: local compiler result and source</summary><p id="leanVersion"></p><pre id="leanOutput"></pre><pre id="leanSource"></pre></details><p id="leanConnection" role="status">Loading the external editor… If it does not connect, use Open full editor.</p><iframe id="leanFrame" title="Interactive Lean editor and proof goals" referrerpolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-forms allow-downloads allow-popups" src="about:blank"></iframe>`;
 document.body.append(dialog);
 const mainButton=document.createElement('button');mainButton.id='openLean';mainButton.textContent='Lean playground';mainButton.onclick=()=>open();q('header').append(mainButton);
 function prepare(id){chosen=data.examples.find(e=>e.id===id)||data.examples[0];q('#leanExample').value=chosen.id;q('#leanScope').textContent=chosen.scope;q('#leanVersion').textContent=data.compiler+' · check applies only to the bundled bytes shown below, not edits.';q('#leanOutput').textContent=chosen.compilerOutput;q('#leanSource').textContent=chosen.code;q('#leanDownload').href=chosen.file;const url='https://live.lean-lang.org/#code='+encodeURIComponent(chosen.code);q('#leanExternal').href=url;return url}
 function load(){const url=prepare(q('#leanExample').value);q('#leanConnection').textContent='Loading external Lean editor. Its own messages show compilation status.';q('#leanFrame').src=url;loadedExample=chosen.id}
 async function open(id){try{await ready;if(!dialog.open)dialog.showModal();prepare(id||loadedExample||data.examples[0].id);if(loadedExample!==chosen.id)load()}catch{alert('Unable to load Lean examples. Refresh and try again.')}}
 q('#leanClose').onclick=()=>dialog.close();q('#leanExample').onchange=()=>{prepare(q('#leanExample').value);q('#leanConnection').textContent='Example selected. Click Load example in editor to replace the current editor contents.'};q('#leanLoad').onclick=load;
 q('#leanFrame').onload=()=>{if(loadedExample)q('#leanConnection').textContent='Editor page loaded. Check its connection and proof messages below; page load alone does not mean the proof passed.'};
 function mount(n){if(!data)return;const e=data.examples.find(e=>e.nodeIds.includes(n.id));if(!e)return;const actions=q('#inspector .actions');if(!actions||q('#nodeLean'))return;const b=document.createElement('button');b.id='nodeLean';b.textContent='Explore Lean example';b.onclick=()=>open(e.id);actions.append(b)}
 const ready=fetch('lean-examples.json?v='+q('meta[name=mathuni-build]').content).then(r=>{if(!r.ok)throw Error('examples');return r.json()}).then(d=>{data=d;q('#leanExample').innerHTML=d.examples.map(e=>'<option value="'+escape(e.id)+'">'+escape(e.title)+'</option>').join('');if(typeof selected!=='undefined'&&selected)mount(nodes.get(selected))});
 // Handle fetch failure without an unhandled rejection; open() displays the error.
 ready.catch(()=>{mainButton.textContent='Lean examples unavailable'});
 window.mathuniLean={mount,open};
})();
